from pathlib import Path
import csv,json,hashlib
import pandas as pd
ROOT=Path(__file__).resolve().parents[4];OUT=Path(__file__).resolve().parent;RES=ROOT/'thucnghiem/results'
stats=list(csv.DictReader((OUT/'statistics.csv').open()))
claims=[]
def claim(id,hyp,status,baseline,metric,filterfn,scope,section,action):
 rr=next(r for r in stats if filterfn(r));claims.append({'claim':id,'hypothesis':hyp,'status':status,'metric':metric,'baseline':baseline,'n':rr['n_independent_pairs'],'delta_improvement':rr['oriented_mean_improvement'],'ci95':rr['ci95_low']+';'+rr['ci95_high'],'raw_p':rr['raw_p'],'Holm_p':rr['Holm_p'],'scope':scope,'source':rr['source'],'report_section':section,'action':action})
claim('RQ1-superiority','Product ARI better than independently selected Additive','NOT_ESTABLISHED','Additive','ARI',lambda r:r['rq']=='RQ1' and r['section']=='baseline' and r['comparator']=='additive_cij_louvain','Generator3.0, 40 test runs','results RQ1/conclusion','Retain negative mean and p>.05, not equivalence')
claim('RQ1-density','Product better at matched density','NOT_ESTABLISHED','Additive matched density','ARI',lambda r:r['rq']=='RQ1' and r['section']=='baseline' and r['comparator']=='additive_cij_louvain_matched_density','same runs, density diagnostic not causal isolation','results RQ1','Keep CI covering zero')
claim('RQ1-copy5','Product stable under fivefold exact transport copies','NOT_SUPPORTED','Product clean baseline','ARI original',lambda r:r['rq']=='RQ1' and r['section']=='stress primary' and r['candidate']=='product_cij_louvain exact_transport_copy_5x' and r['metric']=='ari_original','Primary only, same40 original runs','results stress','Keep collapse; copy2x/5x nonmonotonic, no threshold claim')
claim('RQ2-alignment-legacy','Revised aligns better with latent benefit than legacy','NOT_ESTABLISHED','legacy_raw','NDCG@5',lambda r:r['rq']=='RQ2' and r['candidate']=='duplicate_aware_robust' and r['comparator']=='legacy_raw' and r['metric']=='ndcg_at_5' and r['section'].startswith('alignment'),'Candidate4.1, oracle grouping, 40seeds','results RQ2','Keep insufficient general alignment benefit')
claim('RQ2-alignment-random','Revised aligns better than random','NOT_ESTABLISHED','random','NDCG@5',lambda r:r['rq']=='RQ2' and r['comparator']=='random' and r['metric']=='ndcg_at_5' and r['section'].startswith('alignment'),'same synthetic oracle grouping','results RQ2','Keep revised mean .6669 below random .6763; do not infer significance from means')
for metric in ['latent_harm','deadline_miss_rate']:
 claim('RQ3-nearest-'+metric,'Revised improves dispatch outcome vs nearest first','ADVERSE_COMPARISON','nearest_first',metric,lambda r:r['rq']=='RQ3' and r['section']=='policy {"partition": "product_cij"}' and r['comparator']=='nearest_first' and r['metric']==metric,'Candidate4.1; n40 seeds averaging3 resources','results RQ3/conclusion','Retain negative improvement; no field rescue claim')
with (OUT/'rq-claims.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(claims[0]));w.writeheader();w.writerows(claims)
text='''# Phân tích RQ — bằng chứng đã lưu, không chạy lại campaign\n\nHandoff P01/P02 đã đọc; giữ LR/runtime và data-scope. HEAD/dirty baseline ../run-baseline; source-hashes.json chốt input, protocol.json khóa unit/family/bootstrap/tolerance.\n\nRQ1 hỏi ưu thế Product so với Additive độc lập; calibration20run, test40run041–080, development tách theo notebook. Không dùng test để chọn lại. RQ2/3 Candidate4.1 có development1000…, calibration2000…, test3000–3039, xem manifest/notebook gốc; không trộn với Generator3.0. Nhãn sự kiện, latent benefit/harm và mapping copy là evaluator-only; không được đưa vào inference.\n\n| Claim | Kết luận | Δ cải thiện | CI95% | Holm p |\n|---|---|---:|---|---:|\n'''
for r in claims:text+=f"| {r['claim']} | {r['status']} | {float(r['delta_improvement']):.6f} | {r['ci95']} | {r['Holm_p']} |\n"
text+='''\nRQ1 Product/Additive ARI .9072205/.9190637, Δ−.0118432; 9thắng/19hòa/12thua, rawp.0987/Holm.2560. CI percentile chưa hiệu chỉnh không cùng kiểm định với Wilcoxon/Holm; không chọn phép có lợi, p>.05 không chứng minh tương đương. Matched-density retained fraction .03011/.03021, degree9.90/9.94; Leiden .9164883. Fake absorption/rejection0 nhưng false destinations16.49%, không gọi chống tin giả thành công. Stress primary/replication kiểm riêng300bootstrap rows/bundle; copy2x tăng nhẹ/copy5x giảm mạnh, không xác định threshold collapse. Cơ chế quantile/top-k là interpretation, chưa isolated.\n\nRQ2 oracle grouping: revised NDCG.666889741, random.6763, legacy.65477; không chứng minh superiority/general benefit. Exact-copy2/5/10x score drift0 ở grouping cố định hỗ trợ bất biến hẹp. Tăng N/V và coordinated high-confidence attacks thất bại; boundedness không bảo đảm nguồn thật hoặc graph robustness. 21config×40seed sensitivity có mean span<.01; không validate dispatch constants.\n\nRQ3: từ CSV raw, trung bình ba resource conditions theo seed trước paired inference; n40,14endpoint mỗi fixed contrast. Revised harm tăng14.34vslegacy, trễ hạn giảm1.875đpt nhưng không significant sau Holm. Nearest-first có harm/trễ thấp hơn; Δ oriented−69.8846/−.1770833. Product worse than matched-density Additive under fixed revised score (harm Holm.000168). Không gọi harm mô phỏng là số người thực. Cost/travel/scheduling mismatch là possible mechanism, chưa causal diagnosis.\n\n## Sai lệch và phạm vi replay\n\n- Original verifier base FAILED do CSV benchmark_test_40runs thiếu final LF; bytes khác historical commit, toàn bộ400records/fields bằng nhau. Không sửa source/manifest. verify_stress.py dùng adapter symlink src→thucnghiem, giữ historical git path, chứng minh record equality rồi gọi hàm stress chỉ đọc. Đây là stress replay có bounded base disposition, không full verifier PASS.\n- RQ2 còn8discrepancies:3rawp Spearman (legacy/simple_linear/urgency_only) và5Holm liên quan. Đúng NumPy2.0.2/pandas2.2.2/SciPy1.16.3 cho cùng kết quả replay như env mới, nên không đổ lỗi phiên bản. CSV %.10g đã làm tròn có thể tác động tie ranks, chưa cô lập; không khôi phục độ chính xác bị mất bằng số tưởng tượng. Giữ cả original và replay. NDCG conclusion không đổi.\n- Script exit0 chỉ nghĩa chạy xong, không chứng nhận mọi số khớp. validation.txt và discrepancies.json ghi coverage/thất bại cụ thể. RQ3 env pin theo provenance; tolerances tuyệt đối/relative, p dùng abs1e-12 để không che sai số ở p nhỏ.\n\nChưa tính lại clustering/predictions hoặc validate real-world labels. Không sửa historical CSV/notebook/checkpoint/model/config.\n'''
(OUT/'analysis.md').write_text(text)
text='# Phân tích từng điều kiện\n\nPrimary và replication tách riêng; không tăng n bằng scenario/copy.\n\n'
for prefix,label in [('rq1_results','primary'),('rq1_results_v2/full','replication')]:
 df=pd.read_csv(RES/prefix/'aggregate/rq1_stress_summary.csv');text+=f'## RQ1 {label}\n\n| Scenario | Method | ARI mean | density | false destination % |\n|---|---|---:|---:|---:|\n'
 for _,r in df.iterrows():text+=f'| {r.scenario} | {r.method} | {r.ari_original_mean:.5f} | {r.retained_edge_fraction_mean:.5f} | {r.false_destination_rate_all_mean:.4f} |\n'
df=pd.read_csv(RES/'rq2_results/rq2_parameter_sensitivity_summary.csv');text+='\n## RQ2 sensitivity\n\n'
for param,group in df.groupby('parameter'):
 text+=f"- {param}: min/max mean NDCG {group.mean_ndcg_at_5.min():.8f}/{group.mean_ndcg_at_5.max():.8f}; nguồn rq2_parameter_sensitivity_summary.csv, không retune.\n"
df=pd.read_csv(RES/'rq3_results/rq3_dispatch_test.csv');text+='\n## RQ3 resource conditions: mô tả, không n120\n\n';print('RQ3 resource keys',[x for x in df.columns if 'resource' in x or 'scenario' in x]);key=next(x for x in df.columns if 'scenario' in x)
g=df[(df.partition=='product_cij') & df.policy.isin(['revised_priority','nearest_first','legacy_priority'])].groupby([key,'policy'])[['latent_harm','deadline_miss_rate']].mean()
text+='```text\n'+g.to_string()+'\n```'
(OUT/'condition-analysis.md').write_text(text+'\n')
